const icons = {
  plane: '<path d="m21 3-6.3 18-3.6-8.1L3 9.3 21 3Z"/><path d="m11.1 12.9 5-5"/>',
  shield: '<path d="m12 3 8 3v6c0 4.3-5 7.7-8 9-3-1.3-8-4.7-8-9V6l8-3Z"/><path d="m8.4 12 2.4 2.4 4.8-4.8"/>',
  link: '<path d="m9 15 6-6M8 16l-1.4 1.4a4.2 4.2 0 0 1-6-6L5 7a4.2 4.2 0 0 1 6 0M16 8l1.4-1.4a4.2 4.2 0 0 0-6-6L7 5" transform="translate(3 3) scale(.85)"/><path d="m14 5 1.4-1.4a4.2 4.2 0 0 1 6 6L17 14a4.2 4.2 0 0 1-6 0"/>',
  forward: '<path d="m13 4 7 7-7 7v-5c-5-1-8 1-10 6 0-8 3-12 10-12V4Z"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  users: '<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',
  radio: '<circle cx="12" cy="12" r="2"/><path d="M7.8 7.8a6 6 0 0 0 0 8.4m8.4-8.4a6 6 0 0 1 0 8.4M5 5a10 10 0 0 0 0 14M19 5a10 10 0 0 1 0 14"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  infinity: '<path d="M12 12C6 2 0 8 4 14c4 6 8-2 8-2s4-8 8-2c4 6-2 12-8 2Z"/>',
  lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3m-4 5v2"/>',
  reset: '<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',
};
const icon = (name) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.shield}</svg>`;

function layout(title, description, content, { script = '', robots = 'index,follow', home = false, action = '', lang = 'sw', path = '/' } = {}) {
  lang = normalizeLang(lang);
  const t = translator(lang);
  const homeHref = localeHref('/', lang);
  const privacyHref = localeHref('/privacy', lang);
  const languages = `<div class="language-switch" role="group" aria-label="${t('Chagua lugha', 'Choose language')}"><a href="${path}?lang=sw" lang="sw" hreflang="sw" aria-label="Kiswahili"${lang === 'sw' ? ' aria-current="page"' : ''}>SW</a><a href="${path}?lang=en" lang="en" hreflang="en" aria-label="English"${lang === 'en' ? ' aria-current="page"' : ''}>EN</a></div>`;
  return `<!doctype html>
<html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070c14"><meta name="description" content="${escape(description)}"><meta name="robots" content="${escape(robots)}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${escape(description)}"><meta property="og:type" content="website"><title>${escape(title)}</title><link rel="icon" href="https://sautilink.com/logo.png"><style>${styles}</style></head>
<body><a class="skip" href="#main">${t('Ruka hadi maudhui', 'Skip to content')}</a><div class="container"><header class="nav"><a class="brand" href="${homeHref}" aria-label="SautiLink Pilot — ${t('Mwanzo', 'Home')}"><img src="https://sautilink.com/logo.png" alt="" width="34" height="34"><span class="brand-name">SautiLink <span>Pilot</span></span></a><div class="header-tools"><nav class="nav-links" aria-label="${t('Urambazaji mkuu', 'Main navigation')}"><a href="${homeHref}#jaribu">${t('Jaribu Pilot', 'Try Pilot')}</a><a class="wide-link" href="${homeHref}#sheria">${t('Sheria', 'Rules')}</a><a class="wide-link" href="${privacyHref}">${t('Faragha', 'Privacy')}</a>${action ? `<span class="nav-action">${action}</span>` : ''}</nav>${languages}</div></header>${content}${home ? '<div class="footer-watermark" aria-hidden="true">PILOT</div>' : ''}<footer class="footer"><span>SautiLink Pilot · ${t('Mazungumzo yenye mwelekeo.', 'Keep the conversation on course.')}</span><div class="footer-links"><a href="${privacyHref}">${t('Faragha', 'Privacy')}</a><a href="https://sautilink.com" target="_blank" rel="noopener noreferrer">SautiLink ↗</a><a href="${homeHref}#anza">${t('Mwongozo wa kuanza', 'Getting started')}</a><a href="https://github.com/sautilink/pilot" target="_blank" rel="noopener noreferrer">${t('Kwa developers', 'For developers')} ↗</a></div></footer></div>${script ? `<script>${script}</script>` : ''}</body></html>`;
}

function botAction(username, ready, lang = 'sw') {
  const t = translator(lang);
  const valid = typeof username === 'string' && /^[A-Za-z][A-Za-z0-9_]{4,31}$/.test(username);
  if (!ready || !valid) return `<button class="button" type="button" disabled>${t('Bot inaandaliwa', 'Bot coming soon')}</button>`;
  const href = `https://t.me/${encodeURIComponent(username)}?startgroup=pilot`;
  return `<a class="button" href="${escape(href)}" target="_blank" rel="noopener noreferrer">${icon('plane')}${t('Ongeza kwenye group', 'Add to your group')}</a>`;
}

function homeScript(lang) {
  return `
(() => {
  'use strict';
  const lang = ${JSON.stringify(lang)};
  const t = (sw, en) => lang === 'en' ? en : sw;
  const examples = {
    blocked: { author: 'Juma', avatar: 'J', role: 'Member', type: t('Link iliyokatazwa', "Blocked link"), message: t('Jiunge na ofa hii:\\nhttps://offers.example/today', "Join this offer:\\nhttps://offers.example/today"), forwarded: false, violation: true, reason: t('Kutuma link isiyoruhusiwa.', "Posting an unapproved link.") },
    allowed: { author: 'Asha', avatar: 'A', role: 'Member', type: t('Link ya SautiLink', "SautiLink link"), message: t('Tukutane hapa:\\nhttps://sautilink.com', "Meet us here:\\nhttps://sautilink.com"), forwarded: false, violation: false, title: t('Link halali. Inaendelea.', "Approved link. All clear."), copy: t('Domain ya SautiLink ipo kwenye whitelist. Ujumbe unabaki, bila kuongeza kosa.', "The SautiLink domain is on the whitelist. The message stays, with no added strike.") },
    forward: { author: 'Juma', avatar: 'J', role: 'Member', type: 'Forwarded message', message: t('Tangazo la mfano kutoka channel nyingine.', "An example announcement from another channel."), forwarded: true, violation: true, reason: t('Kutuma forwarded message.', "Posting a forwarded message.") },
    admin: { author: 'Neema', avatar: 'N', role: 'Admin', type: t('Ujumbe wa admin', "Admin message"), message: t('Tangazo la admin:\\nhttps://updates.example/notice', "An admin announcement:\\nhttps://updates.example/notice"), forwarded: false, violation: false, title: t('Admin ana ruhusa.', "Admins have permission."), copy: t('Pilot inathibitisha mamlaka ya admin kabla ya kuangalia links na forwards. Ujumbe huu unaruhusiwa.', "Pilot checks admin status before applying the link and forward rules. This message is allowed.") },
    linked: { author: t('Channel ya group', "Group channel"), avatar: 'C', role: 'Linked channel', type: t('Post rasmi ya channel', "Official channel post"), message: t('Taarifa mpya kutoka channel iliyounganishwa na group hili.', "An update from the channel linked to this group."), forwarded: true, violation: false, title: t('Channel imeunganishwa.', "Linked channel. All clear."), copy: t('Post hii imeingia automatically kutoka linked channel halisi ya group. Inaruhusiwa bila adhabu.', "This post arrived automatically from the actual channel linked to the group. It is allowed without a penalty.") }
  };
  const state = { group: 'A', scenario: 'blocked', strikes: { A: 0, B: 0 } };
  const ids = ['sim-author','sim-role','sim-avatar','sim-message','sim-forward','sim-type','sim-outcome','sim-outcome-label','sim-outcome-icon','sim-outcome-title','sim-outcome-copy','sim-announcement','sim-step-note','sim-count','sim-count-a','sim-count-b','sim-group-label','sim-run','sim-reset'];
  const el = Object.fromEntries(ids.map(id => [id, document.getElementById(id)]));
  const scenarios = Array.from(document.querySelectorAll('[data-scenario]'));
  const groups = Array.from(document.querySelectorAll('[data-sim-group]'));
  const stages = Array.from(document.querySelectorAll('[data-stage]'));
  function clearOutcome() {
    el['sim-outcome'].dataset.tone = 'idle';
    el['sim-outcome-label'].textContent = t('MATOKEO YA MFANO', "DEMO RESULT");
    el['sim-outcome-icon'].textContent = '↗';
    el['sim-outcome-title'].textContent = t('Pilot itafanya nini?', "What will Pilot do?");
    el['sim-outcome-copy'].textContent = t('Chagua mfano, kisha uendeshe kuona uamuzi na sababu yake.', "Choose an example, then run it to see the decision and its reason.");
    el['sim-announcement'].hidden = true;
    el['sim-announcement'].textContent = '';
  }
  function render() {
    const example = examples[state.scenario];
    const strikes = state.strikes[state.group];
    el['sim-author'].textContent = example.author;
    el['sim-role'].textContent = example.role;
    el['sim-avatar'].textContent = example.avatar;
    el['sim-message'].textContent = example.message;
    el['sim-forward'].hidden = !example.forwarded;
    el['sim-forward'].textContent = state.scenario === 'linked' ? 'Forwarded from linked channel' : t('Forwarded from channel ya mfano', "Forwarded from example channel");
    el['sim-type'].textContent = example.type;
    el['sim-group-label'].textContent = 'GROUP ' + state.group + t(' · MFANO', " · DEMO");
    el['sim-count'].textContent = strikes + ' / 3';
    el['sim-count-a'].textContent = state.strikes.A + '/3';
    el['sim-count-b'].textContent = state.strikes.B + '/3';
    el['sim-run'].disabled = example.violation && strikes >= 3;
    el['sim-run'].textContent = example.violation && strikes >= 3 ? t('Permanent ban · anza demo upya', "Permanent ban · reset demo") : example.violation && strikes > 0 ? t('Onyesha kosa linalofuata →', "Show the next offense →") : t('Endesha mfano →', "Run example →");
    el['sim-step-note'].textContent = example.violation && strikes > 0 && strikes < 3 ? t('Kwa kosa linalofuata, demo husogeza muda mbele: ban ya awali imeisha na Juma amerudi.', "For the next offense, the demo moves time forward: the previous ban has expired and Juma has rejoined.") : example.violation && strikes >= 3 ? t('Juma amefikia permanent ban kwenye Group ', "Juma has reached a permanent ban in Group ") + state.group + t('. Jaribu group jingine au anza demo upya.', ". Try the other group or reset the demo.") : t('Mfano unaendeshwa kwenye browser yako tu. Hakuna ujumbe unaotumwa Telegram.', "This example runs only in your browser. No messages are sent to Telegram.");
    scenarios.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.scenario === state.scenario)));
    groups.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.simGroup === state.group)));
    stages.forEach(stage => { const number = Number(stage.dataset.stage); stage.dataset.state = number === strikes ? 'current' : number < strikes ? 'done' : 'waiting'; });
  }
  scenarios.forEach(button => button.addEventListener('click', () => {
    if (!Object.hasOwn(examples, button.dataset.scenario)) return;
    state.scenario = button.dataset.scenario;
    clearOutcome(); render();
  }));
  groups.forEach(button => button.addEventListener('click', () => {
    if (button.dataset.simGroup !== 'A' && button.dataset.simGroup !== 'B') return;
    state.group = button.dataset.simGroup;
    clearOutcome(); render();
  }));
  el['sim-run'].addEventListener('click', () => {
    const example = examples[state.scenario];
    if (example.violation && state.strikes[state.group] >= 3) return;
    if (example.violation) {
      const strike = ++state.strikes[state.group];
      const duration = strike === 1 ? t('saa 24', "24 hours") : strike === 2 ? t('siku 7', "7 days") : 'permanent';
      el['sim-outcome'].dataset.tone = 'blocked';
      el['sim-outcome-label'].textContent = t('UJUMBE UMEONDOLEWA', "MESSAGE REMOVED");
      el['sim-outcome-icon'].textContent = '×';
      el['sim-outcome-title'].textContent = strike === 3 ? 'Permanent ban.' : t('Ban ya ', "Banned for ") + duration + '.';
      el['sim-outcome-copy'].textContent = example.reason + t(' Hili ni kosa la ', " This is strike ") + strike + t(' la Juma kwenye Group ', " for Juma in Group ") + state.group + '.';
      el['sim-announcement'].textContent = t('Juma amefungiwa ', "Juma has been banned ") + (strike === 3 ? t('permanent.', "permanently.") : t('kwa ', "for ") + duration + '.') + t('\\nSababu: ', "\\nReason: ") + example.reason;
      el['sim-announcement'].hidden = false;
    } else {
      el['sim-outcome'].dataset.tone = 'allowed';
      el['sim-outcome-label'].textContent = t('UJUMBE UMERUHUSIWA', "MESSAGE ALLOWED");
      el['sim-outcome-icon'].textContent = '✓';
      el['sim-outcome-title'].textContent = example.title;
      el['sim-outcome-copy'].textContent = example.copy;
      el['sim-announcement'].hidden = true;
      el['sim-announcement'].textContent = '';
    }
    render();
  });
  el['sim-reset'].addEventListener('click', () => {
    state.group = 'A'; state.scenario = 'blocked'; state.strikes.A = 0; state.strikes.B = 0;
    clearOutcome(); render();
  });
  clearOutcome(); render();
})();
`;
}

function featureTools(lang) {
  const t=translator(lang);
  const tools=[
    ['shield',t('Paneli ndani ya Telegram','Your Telegram dashboard'),t('Admins wanaona matukio, takwimu na hali ya group mahali pamoja. Kila group lina mipangilio yake.','Admins see incidents, statistics and group health in one place. Each group keeps its own settings.')],
    ['reset',t('Rufaa yenye nafasi ya kusikilizwa','A clear path to appeal'),t('Member anaweza kuona matukio yake na kuomba ukaguzi faraghani. Admin hufanya uamuzi na historia yake huhifadhiwa.','Members can view their own cases and request a private review. Admins decide, with a record of each decision.')],
    ['link',t('Kagua link kabla ya kutuma','Check a link before posting'),t('Kikagua kinaeleza kama link inaruhusiwa na sheria za Pilot. Admin anaweza kuongeza ruhusa maalumu kwa group lake.','The checker explains whether Pilot’s rules allow a link. Admins can add allowances for their own group.')],
    ['users',t('Karibu inayofanana na jamii yako','A welcome that feels like your community'),t('Chagua ujumbe wa kukaribisha, maelezo ya sheria na mtindo wa matangazo kwa Kiswahili na English.','Choose welcome messages, group rules and announcement styles in Swahili and English.')],
    ['clock',t('Ujumbe mwingi uwe na mipaka','Make room between messages'),t('Admin anaweza kuwasha anti-flood: kuondoa ujumbe uliozidi au kuweka mute ya muda, tofauti na makosa ya link na forward.','Admins can enable flood control to remove excess messages or apply a temporary mute, separately from link and forward strikes.')],
    ['radio',t('Taarifa pale unapozihitaji','Updates when you need them'),t('Washa taarifa za matatizo na ripoti za faragha. Kwa groups zenye join requests, chagua ukaguzi wa admin au hatua fupi ya kukubali sheria.','Opt into private alerts and reports. For groups with join requests, choose admin review or a short rules acknowledgement step.')],
  ];
  return `<section class="section" id="zana" aria-labelledby="tools-title"><div class="section-head"><div><div class="eyebrow">${t('Zaidi ya moderation','More ways to care for your group')}</div><h2 id="tools-title">${t('Udhibiti wako.<br>Nafasi ya kila member.','Your controls.<br>Room for every member.')}</h2></div><p>${t('Zana za ziada huwashwa kwa chaguo la admin. Members wana sehemu yao ya faragha pia.','Additional tools are enabled by an admin. Members have their own private space, too.')}</p></div><div class="tool-grid">${tools.map(([symbol,title,copy])=>`<article class="tool-card">${icon(symbol)}<h3>${title}</h3><p>${copy}</p></article>`).join('')}</div><p class="section-note"><strong>${t('Taarifa za maboresho.', 'Product updates.')}</strong> ${t('Groups zinazotumia Pilot zinaweza kupokea matangazo ya huduma na maboresho kutoka kwa mmiliki wa bot.', 'Groups using Pilot may receive service and product announcements from the bot owner.')}</p><div class="tool-note"><p>${t('Fungua bot, gusa Start, kisha chagua paneli. Taarifa za group zinapatikana kwa admins waliothibitishwa; taarifa za member zinapatikana kwa mwenyewe.','Open the bot, tap Start, then choose the dashboard. Group details are available to verified admins; member records are available to their owner.')}</p><a class="button secondary" href="https://t.me/sautilinkpilotbot?start=home" target="_blank" rel="noopener noreferrer">${t('Fungua Pilot','Open Pilot')} ↗</a></div></section>`;
}

export function renderHome({ username, ready, lang = 'sw' } = {}) {
  lang = normalizeLang(lang);
  const t = translator(lang);
  const usable = Boolean(ready && typeof username === 'string' && /^[A-Za-z][A-Za-z0-9_]{4,31}$/.test(username));
  const action = botAction(username, ready, lang);
  const guide = usable ? `<a class="text-link" href="https://t.me/${encodeURIComponent(username)}" target="_blank" rel="noopener noreferrer">${t('Fungua menyu ya Pilot', 'Open the Pilot menu')} <span aria-hidden="true">↗</span></a>` : '';
  return layout(t('SautiLink Pilot — Group lako. Pilot wako.', 'SautiLink Pilot — Your group. Your Pilot.'), t('Msaidizi wa moderation kwa Telegram. Links na forwards zidhibitiwe, admins waheshimiwe, mazungumzo yaendelee.', 'Your Telegram moderation companion. Manage links and forwards, respect admins, and keep the conversation going.'), `<main id="main">
<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">${t("Imejengwa kwa jamii za Telegram", "Built for Telegram communities")}</div><h1 id="hero-title">${t("Group lako.", "Your group.")}<span class="hero-accent">${t("Pilot wako.", "Your Pilot.")}</span></h1><p class="lead">${t("Mazungumzo mazuri yanahitaji nafasi.", "Good conversations need room to grow.")} <strong>SautiLink Pilot</strong> ${t("huondoa links zisizoruhusiwa na forwards, huku admins wakiendelea kuongoza.", "removes unapproved links and forwards while your admins stay in charge.")}</p><div class="actions">${action}<a class="text-link" href="#jaribu"><span class="play" aria-hidden="true">▶</span>${t("Jaribu inavyofanya kazi", "See how it works")}</a></div><p class="status-note"><span class="status-dot" aria-hidden="true"></span>${usable ? t('Inapatikana Telegram · Ongeza kwenye supergroup lako', 'Available on Telegram · Add to your supergroup') : t('Maandalizi yanaendelea · Unaweza kujaribu demo hapa chini', 'Getting ready · Try the demo below')}</p></div>
<div class="hero-visual" aria-hidden="true"><span class="orbit-label one">${t("PILOT / MODERATION YA TELEGRAM", "PILOT / TELEGRAM MODERATION")}</span><svg class="orbit-svg" viewBox="0 0 600 600" fill="none"><defs><linearGradient id="plane-fill" x1="171" y1="379" x2="420" y2="175" gradientUnits="userSpaceOnUse"><stop stop-color="#28629e"/><stop offset=".52" stop-color="#78c6ec"/><stop offset="1" stop-color="#b3fff0"/></linearGradient><linearGradient id="plane-fold" x1="300" y1="305" x2="390" y2="425" gradientUnits="userSpaceOnUse"><stop stop-color="#1b5085"/><stop offset="1" stop-color="#4fa7ba"/></linearGradient><radialGradient id="orbit-light"><stop stop-color="#29759d" stop-opacity=".19"/><stop offset="1" stop-color="#29759d" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="300" r="280" fill="url(#orbit-light)"/><circle cx="300" cy="300" r="252" stroke="#234253"/><circle cx="300" cy="300" r="201" stroke="#2a4d60" stroke-dasharray="1 9"/><circle cx="300" cy="300" r="144" stroke="#284b5d"/><path d="M300 30v60m0 420v60M30 300h60m420 0h60" stroke="#406377" stroke-width="1"/><g class="orbit-ring"><circle cx="300" cy="300" r="252" stroke="#73c8d5" stroke-width="1.5" stroke-dasharray="85 1499"/><circle cx="300" cy="48" r="4" fill="#91e4df"/><circle cx="552" cy="300" r="3" fill="#4d88a7"/></g><g class="orbit-ring reverse"><circle cx="300" cy="300" r="201" stroke="#609bc7" stroke-dasharray="45 1218"/><circle cx="99" cy="300" r="3" fill="#8fbbf2"/></g><circle class="orbit-glow" cx="300" cy="300" r="107" fill="#215173" fill-opacity=".11"/><path d="m151 322 291-153-96 278-63-108-132-17Z" fill="url(#plane-fill)"/><path d="m283 339 159-170-96 278-63-108Z" fill="url(#plane-fold)"/><path d="m283 339 159-170" stroke="#c5fff1" stroke-opacity=".8" stroke-width="1.4"/><path d="m284 339-7 60 35-29" fill="#173b5a"/><path d="m151 322 291-153-96 278" stroke="#a2eef0" stroke-width="1.2"/><path d="m122 393 52-25m-29 61 43-20m-9 50 31-15" stroke="#5199bd" stroke-width="1.4" stroke-linecap="round" opacity=".5"/><circle cx="102" cy="413" r="3" fill="#6bc3c2" opacity=".6"/></svg><div class="instrument-chip top">${icon('shield')}<div><small>${t("Mamlaka ya admins", "Admin authority")}</small><strong>${t("Yanaheshimiwa", "Respected")}</strong></div></div><div class="instrument-chip bottom">${icon('clock')}<div><small>${t("Hatua zilizo wazi", "Clear consequences")}</small><strong>24h &nbsp;→&nbsp; 7d &nbsp;→&nbsp; ∞</strong></div></div><span class="orbit-label two">SAUTILINK / PILOT</span></div></section>
<div class="hero-strip"><span class="hero-strip-title">${t("Utaratibu. Mwelekeo. Mazungumzo.", "Order. Direction. Conversation.")}</span><span class="hero-strip-item">${icon('link')}${t("Links zinachunguzwa", "Links checked")}</span><span class="hero-strip-item">${icon('forward')}${t("Forwards zinadhibitiwa", "Forwards moderated")}</span><span class="hero-strip-item">${icon('users')}${t("Admins wanaheshimiwa", "Admins respected")}</span></div>
<section class="section demo-section" id="jaribu" aria-labelledby="try-title"><div class="section-head"><div><div class="eyebrow">${t("Pata picha kamili", "See it in action")}</div><h2 id="try-title">${t("Ijaribu. Uone uamuzi.", "Try a message. See the decision.")}</h2></div><p>${t("Chagua ujumbe wa mfano. Angalia Pilot inachoruhusu, inachozuia, na sababu ya kila hatua.", "Choose an example message. See what Pilot allows, what it blocks, and the reason for each decision.")}</p></div><div class="demo-shell"><div class="demo-toolbar"><span class="demo-brand">${icon('plane')}SautiLink Pilot <span class="demo-pill">DEMO</span></span><small>${t("Mifano ya ndani ya browser · Haiunganishi Telegram", "Browser-only examples · No Telegram connection")}</small></div><div class="sim-grid"><aside class="sim-sidebar" aria-label="${t("Chagua aina ya mfano", "Choose an example type")}"><span class="sim-label">${t("01 / Chagua ujumbe", "01 / Choose a message")}</span><button class="scenario" data-scenario="blocked" aria-pressed="true" type="button">${icon('link')}${t("Link iliyokatazwa", "Blocked link")}</button><button class="scenario" data-scenario="allowed" aria-pressed="false" type="button">${icon('check')}${t("Link ya SautiLink", "SautiLink link")}</button><button class="scenario" data-scenario="forward" aria-pressed="false" type="button">${icon('forward')}Forwarded message</button><button class="scenario" data-scenario="admin" aria-pressed="false" type="button">${icon('users')}${t("Admin anapost", "Admin posting")}</button><button class="scenario" data-scenario="linked" aria-pressed="false" type="button">${icon('radio')}Linked channel</button><p class="sim-private">${icon('lock')}${t("Mifano hii haihifadhiwi na haitumiwi kuchukua hatua kwa mtu yeyote.", "These examples are not saved and never take action against anyone.")}</p></aside><div class="sim-chat"><div class="group-switch" role="group" aria-label="${t("Group la mfano", "Demo group")}"><button class="group-button" data-sim-group="A" aria-pressed="true" type="button">Group A <span class="group-count" id="sim-count-a">0/3</span></button><button class="group-button" data-sim-group="B" aria-pressed="false" type="button">Group B <span class="group-count" id="sim-count-b">0/3</span></button></div><div class="sim-chat-label"><span id="sim-group-label">${t("GROUP A · MFANO", "GROUP A · DEMO")}</span><span id="sim-type">${t("Link iliyokatazwa", "Blocked link")}</span></div><div class="sim-message-row"><div class="sim-avatar" id="sim-avatar" aria-hidden="true">J</div><div class="sim-bubble"><div class="sim-author-line"><span class="sim-author" id="sim-author">Juma</span><span class="sim-role" id="sim-role">Member</span></div><div class="sim-forward" id="sim-forward" hidden></div><p class="sim-message" id="sim-message">${t("Jiunge na ofa hii:", "Join this offer:")}<br>https://offers.example/today</p><div class="sim-message-time">${t("UJUMBE WA MFANO", "EXAMPLE MESSAGE")}</div></div></div><div class="sim-controls"><button class="button" id="sim-run" type="button">${t("Endesha mfano →", "Run example →")}</button><p class="sim-step-note" id="sim-step-note">${t("Mfano unaendeshwa kwenye browser yako tu. Hakuna ujumbe unaotumwa Telegram.", "This example runs only in your browser. No messages are sent to Telegram.")}</p></div></div><div class="sim-outcome" id="sim-outcome" data-tone="idle"><div class="outcome-top"><span id="sim-outcome-label">${t("MATOKEO YA MFANO", "DEMO RESULT")}</span><span aria-hidden="true">↙</span></div><div class="sim-outcome-icon" id="sim-outcome-icon" aria-hidden="true">↗</div><h3 class="sim-outcome-title" id="sim-outcome-title" aria-live="polite">${t("Pilot itafanya nini?", "What will Pilot do?")}</h3><p class="sim-outcome-copy" id="sim-outcome-copy">${t("Chagua mfano, kisha uendeshe kuona uamuzi na sababu yake.", "Choose an example, then run it to see the decision and its reason.")}</p><p class="sim-announcement" id="sim-announcement" hidden></p><div class="sim-count-label"><span>${t("Makosa ya Juma · group hili", "Juma’s strikes · this group")}</span><strong id="sim-count">0 / 3</strong></div><div class="sim-ladder" aria-label="${t("Hatua za adhabu", "Penalty stages")}"><div class="sim-stage" data-stage="1" data-state="waiting">01 · ${t("Saa 24", "24 hours")}</div><div class="sim-stage" data-stage="2" data-state="waiting">02 · ${t("Siku 7", "7 days")}</div><div class="sim-stage" data-stage="3" data-state="waiting">03 · Permanent</div></div></div></div><div class="demo-footer"><span>${t("Historia ya Group A na Group B inajitegemea.", "Group A and Group B have separate histories.")}</span><button class="sim-reset" id="sim-reset" type="button">${icon('reset')}${t("Anza demo upya", "Reset demo")}</button></div></div><div class="demo-caption"><span>${t("Mfano wa tangazo · Si tukio halisi", "Example announcement · Not a real event")}</span><span>${t("Muda wa adhabu husogezwa mbele kwenye demo pekee.", "Time moves forward only inside this demo.")}</span></div><noscript><p class="section-note">${t("Washa JavaScript ili kuendesha demo. Sheria zote zimeelezwa hapa chini.", "Enable JavaScript to run the demo. All the rules are explained below.")}</p></noscript></section>
<section class="section" id="sheria" aria-labelledby="rules-title"><div class="section-head"><div><div class="eyebrow">${t("Msimamo unaoeleweka", "Rules everyone can understand")}</div><h2 id="rules-title">${t("Kosa likijirudia,<br>hatua inaongezeka.", "Repeat offenses.<br>Stronger consequences.")}</h2></div><p>${t("Ujumbe unaondolewa. Adhabu inatekelezwa. Group linaona jina, muda na sababu.", "The message is removed. The penalty is applied. The group sees the member’s name, duration, and reason.")}</p></div><div class="policy-grid"><article class="policy-card" data-number="01"><div class="policy-head">${t("KOSA LA KWANZA", "FIRST OFFENSE")} ${icon('clock')}</div><div class="policy-duration">${t("Saa 24", "24 hours")}</div><p>${t("Mtumiaji anaondolewa kwenye group kwa siku moja.", "The member is removed from the group for one day.")}</p></article><article class="policy-card" data-number="02"><div class="policy-head">${t("KOSA LA PILI", "SECOND OFFENSE")} ${icon('clock')}</div><div class="policy-duration">${t("Siku 7", "7 days")}</div><p>${t("Kosa jipya baada ya kurudi linaongeza muda wa ban.", "A new offense after rejoining increases the ban duration.")}</p></article><article class="policy-card" data-number="03"><div class="policy-head">${t("KOSA LA TATU", "THIRD OFFENSE")} ${icon('infinity')}</div><div class="policy-duration">Permanent</div><p>${t("Ban inaendelea mpaka admin abadilishe uamuzi.", "The ban stays in place until an admin changes it.")}</p></article></div><p class="section-note">${t("Makosa huhesabiwa kwa kila mtumiaji ndani ya group husika. Kuisha kwa ban hakufuti historia; admin anaweza kuisafisha. Ban ya muda ikiisha, mtumiaji anaweza kujiunga tena ikiwa group linaruhusu. Harudishwi automatically.", "Strikes are counted per member, within each group. An expired ban does not erase that history; an admin can reset it. Once a temporary ban ends, the member may rejoin if the group allows it. They are not added back automatically.")}</p></section>
${featureTools(lang)}
<section class="section authority" aria-labelledby="authority-title"><div class="authority-copy"><div class="eyebrow">${t("Wewe unaendelea kuongoza", "You stay in charge")}</div><h2 id="authority-title">${t("Pilot inasaidia.<br>Admins wanaamua.", "Pilot assists.<br>Admins decide.")}</h2><p>${t("Moderation inapaswa kurahisisha kazi ya admins. Pilot inatambua ruhusa zao kabla ya kuchukua hatua.", "Moderation should make life easier for admins. Pilot checks their authority before taking action.")}</p><div class="authority-mark">${icon('shield')}${t("Mamlaka ya group yanaheshimiwa.", "Your group’s authority is respected.")}</div></div><ul class="authority-list"><li class="authority-item"><div class="authority-icon">${icon('users')}</div><div><h3>${t("Owner na admins", "Owner and admins")}</h3><p>${t("Wanaweza kutuma links na forwarded messages. Ujumbe wa anonymous admins unaheshimiwa pia.", "They can post links and forwarded messages. Messages from anonymous admins are also respected.")}</p></div></li><li class="authority-item"><div class="authority-icon">${icon('radio')}</div><div><h3>${t("Channel iliyounganishwa", "Linked channel")}</h3><p>${t("Posts zinazoingia automatically kutoka linked channel halisi ya group zinaruhusiwa.", "Posts arriving automatically from the group’s actual linked channel are allowed.")}</p></div></li><li class="authority-item"><div class="authority-icon">${icon('reset')}</div><div><h3>${t("Uamuzi wa admin unabaki", "Admin decisions stand")}</h3><p>${t("Admin akibadilisha adhabu, Pilot haiirudishi kwa kosa lilelile la zamani. Kosa jipya linashughulikiwa kivyake.", "When an admin changes a penalty, Pilot does not reapply it for the same old incident. Any new offense is handled separately.")}</p></div></li></ul></section>
<section class="section" aria-labelledby="allow-title"><div class="section-head"><div><div class="eyebrow">${t("Viungo vilivyoidhinishwa", "Approved links")}</div><h2 id="allow-title">${t("Njia halali zinabaki wazi.", "Keep trusted links flowing.")}</h2></div><p>${t("Whitelist inaruhusu kurasa zote za SautiLink na links za channels hizi, pamoja na posts zake.", "The whitelist allows all SautiLink pages and these Telegram channel links, including their posts.")}</p></div><div class="allow-shell"><div class="allow-top"><div><a class="allow-domain" href="https://sautilink.com" target="_blank" rel="noopener noreferrer">sautilink<span>.com</span></a><p class="allow-domain-desc">${t("Domain moja. Kurasa zake zote. Subdomains zake zote.", "One domain. Every page. Every subdomain.")}</p></div><div class="allow-badges"><span class="allow-badge">https://sautilink.com/*</span><span class="allow-badge">https://www.sautilink.com/*</span><span class="allow-badge">https://*.sautilink.com/*</span></div></div><div class="channel-links"><a class="channel-link" href="https://t.me/techhubtz" target="_blank" rel="noopener noreferrer"><span class="channel-link-top">${icon('plane')}<span aria-hidden="true">↗</span></span><strong>t.me/techhubtz</strong></a><a class="channel-link" href="https://t.me/sautilink" target="_blank" rel="noopener noreferrer"><span class="channel-link-top">${icon('plane')}<span aria-hidden="true">↗</span></span><strong>t.me/sautilink</strong></a><a class="channel-link" href="https://t.me/sautilink_cloud" target="_blank" rel="noopener noreferrer"><span class="channel-link-top">${icon('plane')}<span aria-hidden="true">↗</span></span><strong>t.me/sautilink_cloud</strong></a><a class="channel-link" href="https://t.me/drcharlesofficial" target="_blank" rel="noopener noreferrer"><span class="channel-link-top">${icon('plane')}<span aria-hidden="true">↗</span></span><strong>t.me/drcharlesofficial</strong></a></div><p class="allow-note">${t("Ruhusa ya link haibadilishi sheria ya forwards. Ujumbe wenye link halali pamoja na iliyokatazwa bado unakiuka sheria.", "An approved link does not override the forward rule. A message containing both approved and blocked links still breaks the rules.")}</p></div></section>
<section class="section onboarding" id="anza" aria-labelledby="start-title"><div><div class="eyebrow">${t("Safari inaanza hapa", "Your journey starts here")}</div><h2 id="start-title">${t("Hatua tatu.<br>Pilot yuko ndani.", "Three steps.<br>Pilot is on board.")}</h2><p class="lead">${t("Tumia bot hiyohiyo kwenye groups unazosimamia. Kila group lina historia yake.", "Use the same bot across the groups you manage. Each group keeps its own history.")}</p><div class="actions">${guide}</div></div><ol class="setup-steps"><li><strong>${t("Ongeza Pilot kwenye group.", "Add Pilot to your group.")}</strong>${t("Bonyeza “Ongeza kwenye group”, kisha chagua supergroup unalosimamia kwenye Telegram.", "Select “Add to your group”, then choose a Telegram supergroup you manage.")}</li><li><strong>${t("Ipe ruhusa za admin.", "Give it admin permissions.")}</strong>${t("Ruhusu kufuta ujumbe na kufungia wanachama ili sheria zifanye kazi.", "Allow it to delete messages and ban members so it can enforce the rules.")}</li><li><strong>${t("Wajulishe wanachama sheria.", "Let members know the rules.")}</strong>${t("Links zisizoruhusiwa na forwards zitasababisha saa 24, siku 7, kisha permanent ban.", "Unapproved links and forwards lead to a 24-hour ban, then 7 days, then a permanent ban.")}</li></ol></section>
<section class="section faq-layout" aria-labelledby="faq-title"><div class="section-head"><div><div class="eyebrow">${t("Maswali ya kawaida", "Common questions")}</div><h2 id="faq-title">${t("Kabla ya<br>kuanza.", "Before<br>you begin.")}</h2></div></div><div class="faq"><details><summary>${t("Je, forward kutoka channel iliyo kwenye whitelist inaruhusiwa?", "Are forwards from a whitelisted channel allowed?")}</summary><p>${t("Whitelist ni ya links. Forwarded message ya member wa kawaida bado inakatazwa, hata kama channel yake ipo kwenye whitelist. Msamaha wa admins na posts zinazoingia automatically kutoka linked channel unaendelea kutumika.", "The whitelist applies to links. A regular member’s forwarded message is still blocked, even if its channel is whitelisted. The exceptions for admins and automatic posts from the group’s linked channel still apply.")}</p></details><details><summary>${t("Ni aina gani ya group inayohitajika?", "What type of group does Pilot need?")}</summary><p>${t("Ban za saa 24 na siku 7 hutumia uwezo wa Telegram supergroups. Group la zamani la aina ya basic group linahitaji kuboreshwa kabla ya moderation yenye ban za muda kuanza.", "The 24-hour and 7-day bans use Telegram’s supergroup features. An older basic group needs to be upgraded before moderation with timed bans can begin.")}</p></details><details><summary>${t("Ban ikiisha, mtumiaji hurudishwa mwenyewe?", "Does a member return automatically when a ban expires?")}</summary><p>${t("Hapana. Anaweza kujiunga tena ikiwa group linaruhusu, lakini Telegram haimrudishi automatically. Historia yake ya makosa ndani ya group hilo inabaki mpaka admin aisafishe.", "No. They may rejoin if the group allows it, but Telegram does not add them back automatically. Their strike history in that group remains until an admin resets it.")}</p></details><details><summary>${t("Je, Pilot inaweza kutambua kila kitu kilichonakiliwa?", "Can Pilot detect every piece of copied content?")}</summary><p>${t("Pilot hutambua forwarded messages zenye taarifa ya forward. Maandishi ya copy-paste na media iliyopakiwa upya bila taarifa hiyo haviwezi kutambuliwa kwa uhakika kama forwards. Links zilizomo bado huchunguzwa.", "Pilot detects messages that carry Telegram’s forward information. Copy-pasted text and reuploaded media without that information cannot reliably be identified as forwards. Any links they contain are still checked.")}</p></details><details><summary>${t("Kuna nini kingine cha kujua kuhusu ban?", "What else should I know about bans?")}</summary><p>${t("Telegram inaweza kufuta pia ujumbe mwingine wa mtumiaji anapopigwa ban kwenye supergroup. Jaribu bot kwenye group la majaribio kabla ya kuanza kuisimamia jamii yako.", "Telegram may also delete a member’s other messages when they are banned from a supergroup. Try the bot in a test group before using it with your community.")}</p></details><details><summary>${t("Makosa yangu kwenye group moja yanaathiri group jingine?", "Do strikes in one group affect another group?")}</summary><p>${t("Hapana. Historia inahifadhiwa kwa mtumiaji na group husika. Kosa kwenye Group A halikuanzishii adhabu ya pili kwenye Group B.", "No. History belongs to a specific member in a specific group. An offense in Group A does not start you at the second penalty in Group B.")}</p></details></div></section>
<section class="final-cta" aria-labelledby="final-title"><div><div class="eyebrow">SautiLink Pilot</div><h2 id="final-title">${t("Ipe jamii yako nafasi<br>ya kuzungumza.", "Give your community<br>room to talk.")}</h2><p>${t("Ongeza Pilot. Weka sheria wazi. Endelea na mazungumzo.", "Add Pilot. Make the rules clear. Keep the conversation going.")}</p></div>${action}</section></main>`, { script: homeScript(lang), home: true, action, lang });
}

function setupScript(lang) {
  return `
(() => {
  'use strict';
  const lang = ${JSON.stringify(lang)};
  const t = (sw, en) => lang === 'en' ? en : sw;
  const form = document.getElementById('setup-form');
  const key = document.getElementById('setup-key');
  const generated = document.getElementById('generated-key');
  const feedback = document.getElementById('feedback');
  const keyFeedback = document.getElementById('key-feedback');
  const output = document.getElementById('setup-result');
  const connect = document.getElementById('connect');
  const check = document.getElementById('check-status');
  const copy = document.getElementById('copy-key');
  const ownerCheck = document.getElementById('owner-check');
  const ownerPair = document.getElementById('owner-pair');
  const ownerFeedback = document.getElementById('owner-feedback');
  const ownerBound = document.getElementById('owner-bound');
  const ownerNext = document.getElementById('owner-next');
  const ownerPairing = document.getElementById('owner-pairing');
  const ownerCommand = document.getElementById('owner-command');
  const ownerExpiry = document.getElementById('owner-expiry');
  const ownerCopy = document.getElementById('owner-copy');
  let ownerExpiryTimer = null;
  let busy = false;
  function clearPairing() {
    if (ownerExpiryTimer !== null) clearTimeout(ownerExpiryTimer);
    ownerExpiryTimer = null;
    ownerCommand.value = '';
    ownerExpiry.textContent = '';
    ownerPairing.hidden = true;
    ownerCopy.disabled = true;
  }
  function ownerNotify(message, error = false) {
    ownerFeedback.textContent = message;
    ownerFeedback.classList.toggle('error', Boolean(error));
  }
  function clearOwnerState() {
    clearPairing();
    ownerPair.hidden = true;
    ownerBound.hidden = true;
    ownerBound.textContent = '';
    ownerNext.hidden = true;
    ownerNext.textContent = '';
    ownerNotify(t('Tumia ufunguo ulioandika hapo juu kukagua akaunti ya mmiliki.', 'Use the key entered above to check the owner account.'));
  }
  function renderOwner(owner) {
    if (!owner || owner.expectedUsername !== 'drcharlestz' || typeof owner.bound !== 'boolean') return false;
    if (owner.bound) {
      if (!/^[1-9][0-9]{0,15}$/.test(String(owner.userId || ''))) return false;
      clearPairing();
      ownerPair.hidden = true;
      ownerBound.textContent = t('Mmiliki amethibitishwa: @drcharlestz · Telegram ID ', 'Verified owner: @drcharlestz · Telegram ID ') + String(owner.userId);
      ownerBound.hidden = false;
      ownerNext.textContent = t('Fungua bot faraghani kwa akaunti hii, tumia /updates kuona taarifa za mmiliki, kisha /broadcast kuandaa tangazo. Utaona hakiki na kuthibitisha kabla ya kutuma.', 'Open the bot privately using this account. Use /updates for owner information, then /broadcast to prepare an announcement. You will preview and confirm it before sending.');
      ownerNext.hidden = false;
      ownerNotify(t('Akaunti ya mmiliki imeunganishwa. Haiwezi kubadilishwa kupitia ukurasa huu.', 'The owner account is connected. It cannot be changed from this page.'));
    } else {
      ownerBound.hidden = true;
      ownerBound.textContent = '';
      ownerNext.hidden = true;
      ownerNext.textContent = '';
      ownerPair.hidden = false;
      ownerNotify(t('Akaunti ya mmiliki bado haijaunganishwa. Tengeneza amri ya mara moja kwa @drcharlestz.', 'The owner account is not connected yet. Generate a one-time command for @drcharlestz.'));
    }
    return true;
  }
  function setBusy(value) {
    busy = value;
    connect.disabled = value;
    check.disabled = value;
    ownerCheck.disabled = value;
    ownerPair.disabled = value;
  }
  key.addEventListener('input', clearOwnerState);
  function notify(message, error) {
    feedback.textContent = message;
    feedback.classList.toggle('error', Boolean(error));
  }
  document.getElementById('generate-key').addEventListener('click', () => {
    if (!globalThis.crypto || !globalThis.crypto.getRandomValues) {
      keyFeedback.textContent = t('Browser hii haiwezi kutengeneza key salama. Tumia browser ya kisasa kupitia HTTPS.', "This browser cannot generate a secure key. Use a modern browser over HTTPS.");
      return;
    }
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    generated.value = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
    key.value = generated.value;
    clearOwnerState();
    copy.disabled = false;
    keyFeedback.textContent = t('Key mpya imetengenezwa kwenye browser yako. Nakili na uihifadhi kwenye Cloudflare kama SETUP_KEY kabla ya kuunganisha.', "A new key was generated in your browser. Copy it and save it in Cloudflare as SETUP_KEY before connecting.");
  });
  copy.addEventListener('click', async () => {
    if (!generated.value) return;
    try {
      await navigator.clipboard.writeText(generated.value);
      keyFeedback.textContent = t('Imenakiliwa. Weka value hii kwenye Cloudflare Secret inayoitwa SETUP_KEY, kisha uhifadhi mabadiliko.', "Copied. Put this value in the Cloudflare Secret named SETUP_KEY, then save your changes.");
    } catch {
      generated.focus();
      generated.select();
      keyFeedback.textContent = t('Ruhusu clipboard au nakili value ya key mwenyewe. Key haijahifadhiwa kwenye browser.', "Allow clipboard access or copy the key manually. The key has not been saved in your browser.");
    }
  });
  async function run(mode) {
    if (busy) return;
    if (!form.reportValidity()) return;
    const secret = key.value.trim();
    if (secret.length < 32) { notify(t('SETUP_KEY inahitaji angalau herufi 32.', "SETUP_KEY must contain at least 32 characters."), true); return; }
    setBusy(true);
    output.hidden = true;
    notify(mode === 'connect' ? t('Inaunganisha Telegram na database…', "Connecting Telegram and the database…") : t('Inakagua hali ya muunganisho…', "Checking connection status…"));
    try {
      const response = await fetch((mode === 'connect' ? '/api/setup' : '/api/setup/status') + (lang === 'en' ? '?lang=en' : ''), {
        method: mode === 'connect' ? 'POST' : 'GET',
        headers: { 'Authorization': 'Bearer ' + secret, ...(mode === 'connect' ? { 'Content-Type': 'application/json' } : {}) },
        ...(mode === 'connect' ? { body: '{}' } : {}),
        credentials: 'omit',
        cache: 'no-store',
        redirect: 'error',
        signal: AbortSignal.timeout(30000)
      });
      let data;
      try { data = await response.json(); } catch { throw new Error(t('Server imerudisha jibu lisilotarajiwa. Jaribu tena baada ya deploy kukamilika.', "The server returned an unexpected response. Try again after deployment completes.")); }
      if (!response.ok || data.ok === false) {
        const message = typeof data.error === 'string' ? data.error : typeof data.message === 'string' ? data.message : t('Muunganisho haujafanikiwa (HTTP ', "Connection failed (HTTP ") + response.status + ').';
        throw new Error(message);
      }
      const summary = {};
      for (const field of ['ready', 'username', 'webhook_url', 'database', 'status']) {
        if (data[field] !== undefined) summary[field] = data[field];
      }
      output.textContent = JSON.stringify(summary, null, 2).replaceAll(secret, t('[siri]', "[secret]"));
      output.hidden = false;
      if (key.value.trim() === secret && data.owner) renderOwner(data.owner);
      notify(data.ready ? t('Bot imeunganishwa. Unaweza kuijaribu kwenye supergroup la majaribio.', "The bot is connected. You can try it in a test supergroup.") : t('Ukaguzi umekamilika. Angalia hali iliyo hapa chini.', "The check is complete. Review the status below."));
    } catch (error) {
      const message = error && error.name === 'TimeoutError' ? t('Ombi limechukua muda mrefu. Kagua hali kabla ya kujaribu kuunganisha tena.', "The request timed out. Check the status before trying to connect again.") : (error && error.message ? error.message : t('Imeshindikana kuwasiliana na server.', "Unable to reach the server."));
      notify(String(message).replaceAll(secret, t('[siri]', "[secret]")), true);
    } finally {
      setBusy(false);
    }
  }
  function ownerError(code, status) {
    if (status === 401 || status === 403) return t('Ufunguo haujakubaliwa. Kagua ufunguo ulioandika na ujaribu tena.', 'The key was not accepted. Check the key you entered and try again.');
    if (code === 'owner_bound') return t('Mmiliki tayari ameunganishwa. Bofya “Kagua mmiliki” kuona hali iliyothibitishwa.', 'An owner is already connected. Select “Check owner” to see the verified status.');
    if (code === 'owner_pair_rate_limited' || status === 429) return t('Subiri kidogo kabla ya kutengeneza amri nyingine.', 'Wait a little before generating another command.');
    if (code === 'owner_setup_not_ready') return t('Kamilisha muunganisho wa Pilot kwanza, kisha uunganishe akaunti ya mmiliki.', 'Complete the Pilot connection first, then connect the owner account.');
    return t('Hatukuweza kukamilisha ombi hili. Kagua hali ya mmiliki kabla ya kujaribu tena.', 'We could not complete this request. Check the owner status before trying again.');
  }
  async function runOwner(mode) {
    if (busy || !form.reportValidity()) return;
    const secret = key.value.trim();
    if (secret.length < 32) { ownerNotify(t('Weka ufunguo wako wenye angalau herufi 32 hapo juu.', 'Enter your key of at least 32 characters above.'), true); return; }
    setBusy(true);
    if (mode === 'pair') clearPairing();
    ownerNotify(mode === 'pair' ? t('Inaandaa amri ya mara moja…', 'Preparing a one-time command…') : t('Inakagua akaunti ya mmiliki…', 'Checking the owner account…'));
    try {
      const response = await fetch((mode === 'pair' ? '/api/setup/owner' : '/api/setup/status') + (lang === 'en' ? '?lang=en' : ''), {
        method: mode === 'pair' ? 'POST' : 'GET',
        headers: { Authorization: 'Bearer ' + secret, ...(mode === 'pair' ? { 'Content-Type': 'application/json' } : {}) },
        ...(mode === 'pair' ? { body: JSON.stringify({ action: 'pair' }) } : {}),
        credentials: 'omit', cache: 'no-store', redirect: 'error', signal: AbortSignal.timeout(30000)
      });
      let data;
      try { data = await response.json(); } catch { throw new Error(ownerError('', response.status)); }
      if (key.value.trim() !== secret) return;
      if (!response.ok || data.ok === false) {
        if (data.error === 'owner_bound' || response.status === 401 || response.status === 403) clearOwnerState();
        throw new Error(ownerError(data.error || data.code, response.status));
      }
      if (!renderOwner(data.owner)) throw new Error(ownerError('', 503));
      if (mode === 'pair' && !data.owner.bound) {
        const pairing = data.pairing;
        if (!pairing || pairing.username !== 'drcharlestz' || typeof pairing.command !== 'string' || !new RegExp('^/claimowner [A-Za-z0-9._~-]{16,256}$').test(pairing.command) || !Number.isSafeInteger(pairing.expiresAt) || pairing.expiresAt <= 0) throw new Error(ownerError('', 503));
        ownerCommand.value = pairing.command;
        const expires = new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : 'sw-TZ', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Africa/Dar_es_Salaam' }).format(new Date(pairing.expiresAt * 1000));
        ownerExpiry.textContent = t('Inatumika mara moja na inaisha ndani ya dakika 10: ', 'One use only. Expires within 10 minutes: ') + expires + ' EAT.';
        ownerPairing.hidden = false;
        ownerCopy.disabled = false;
        ownerNotify(t('Amri iko tayari. Itume kwa bot faraghani ukiwa umeingia kama @drcharlestz, kisha kagua mmiliki hapa.', 'The command is ready. Send it privately to the bot while signed in as @drcharlestz, then check the owner here.'));
        ownerExpiryTimer = setTimeout(() => { clearPairing(); ownerNotify(t('Amri hii imeisha muda. Kagua hali; kama mmiliki hajaunganishwa, tengeneza amri mpya.', 'This command has expired. Check the status; if the owner is not connected, generate a new command.')); }, Math.max(1, Math.min(600000, pairing.expiresAt * 1000 - Date.now())));
      }
    } catch (error) {
      if (key.value.trim() !== secret) return;
      clearPairing();
      ownerNotify(error && error.name === 'TimeoutError' ? t('Ombi limechukua muda mrefu. Kagua hali ya mmiliki kabla ya kujaribu tena.', 'The request timed out. Check the owner status before trying again.') : String(error && error.message ? error.message : ownerError('', 503)).replaceAll(secret, t('[siri]', '[secret]')), true);
    } finally { setBusy(false); }
  }
  ownerCopy.addEventListener('click', async () => {
    if (!ownerCommand.value || ownerPairing.hidden) return;
    try { await navigator.clipboard.writeText(ownerCommand.value); ownerNotify(t('Imenakiliwa. Itume kwa @sautilinkpilotbot faraghani ukiwa @drcharlestz.', 'Copied. Send it privately to @sautilinkpilotbot while signed in as @drcharlestz.')); }
    catch { ownerCommand.focus(); ownerCommand.select(); ownerNotify(t('Nakili amri iliyoonyeshwa mwenyewe, kisha itume kwa bot faraghani.', 'Copy the displayed command manually, then send it to the bot privately.')); }
  });
  ownerCheck.addEventListener('click', () => runOwner('status'));
  ownerPair.addEventListener('click', () => runOwner('pair'));
  form.addEventListener('submit', event => { event.preventDefault(); return run('connect'); });
  check.addEventListener('click', () => run('status'));
})();
`;
}

export function renderSetup(lang = 'sw') {
  lang = normalizeLang(lang);
  const t = translator(lang);
  return layout(t('Unganisha SautiLink Pilot — Operator setup', 'Connect SautiLink Pilot — Operator setup'), t('Sanidi muunganisho wa Telegram na SautiLink Pilot.', 'Configure the connection between Telegram and SautiLink Pilot.'), `<main id="main" class="document"><div class="eyebrow">${t("Kwa msimamizi wa SautiLink Pilot", "For the SautiLink Pilot operator")}</div><h1>${t("Unganisha Pilot.", "Connect Pilot.")}</h1><p class="lead">${t("Hapa ndipo unapounganisha bot iliyoundwa kupitia BotFather na Worker yako. Admins wa groups hawahitaji ukurasa huu.", "Connect the bot you created through BotFather to your Worker here. Group admins do not need this page.")}</p><ol class="setup-steps"><li><strong>${t("Hifadhi token kwenye Cloudflare.", "Save the token in Cloudflare.")}</strong>${t("Fungua Worker → Settings → Variables and Secrets. Ongeza Secret yenye jina <code>BOT_TOKEN</code> na value ya token uliyopewa na BotFather. Token haitumwi kupitia fomu hii.", "Open your Worker → Settings → Variables and Secrets. Add a Secret named <code>BOT_TOKEN</code> with the token BotFather gave you. This form never asks for or sends that token.")}</li><li><strong>${t("Weka ufunguo wa setup.", "Set your setup key.")}</strong>${t("Tengeneza key hapa chini au tumia key yako yenye angalau herufi 32 za nasibu. Ihifadhi kwenye Cloudflare kama Secret yenye jina <code>SETUP_KEY</code>.", "Generate a key below or use your own key with at least 32 random characters. Save it in Cloudflare as a Secret named <code>SETUP_KEY</code>.")}</li><li><strong>${t("Hakikisha code na D1 vimeunganishwa.", "Check that the code and D1 are connected.")}</strong>${t("Worker inahitaji database ya D1 yenye binding <code>DB</code>. Hifadhi mabadiliko ya Secrets na uhakikishe deployment imekamilika.", "The Worker needs a D1 database with the <code>DB</code> binding. Save your Secret changes and make sure deployment is complete.")}</li></ol><section class="panel" aria-labelledby="key-title"><h2 id="key-title" style="margin-top:0">${t("Tengeneza SETUP_KEY", "Generate SETUP_KEY")}</h2><p class="field-note">${t("Key hutengenezwa ndani ya browser yako. Inabaki kwenye ukurasa huu tu; hifadhi nakala kwenye password manager yako kabla ya kuondoka.", "The key is generated inside your browser and remains only on this page. Save a copy in your password manager before leaving.")}</p><div class="key-actions"><button type="button" class="button secondary" id="generate-key">${t("Tengeneza key salama", "Generate a secure key")}</button><button type="button" class="button secondary" id="copy-key" disabled>${t("Nakili key", "Copy key")}</button></div><div class="form-field"><label for="generated-key">${t("Key iliyotengenezwa", "Generated key")}</label><input class="input" id="generated-key" type="password" readonly autocomplete="off" spellcheck="false" aria-describedby="key-feedback"></div><p class="setup-feedback" id="key-feedback" role="status" aria-live="polite">${t("Ukibofya “Tengeneza”, utapata key ya herufi 64.", "Select “Generate” to create a 64-character key.")}</p></section><section class="panel" aria-labelledby="connect-title"><h2 id="connect-title" style="margin-top:0">${t("Kamilisha muunganisho", "Complete the connection")}</h2><p class="field-note">${t("Tumia SETUP_KEY ileile uliyohifadhi kwenye Cloudflare. Kitufe cha kuunganisha huandaa database na kuweka Telegram webhook ya Worker hii.", "Use the same SETUP_KEY you saved in Cloudflare. Connecting prepares the database and sets the Telegram webhook for this Worker.")}</p><form id="setup-form" method="post" action="/api/setup"><div class="form-field"><label for="setup-key">SETUP_KEY</label><input class="input" id="setup-key" type="password" minlength="32" maxlength="512" required autocomplete="off" spellcheck="false" placeholder="${t("Weka key yako ya setup", "Enter your setup key")}" aria-describedby="auth-help"><span class="field-note" id="auth-help">${t("Key inatumwa kwa Worker hii kupitia HTTPS, kwenye Authorization header.", "The key is sent to this Worker over HTTPS in the Authorization header.")}</span></div><div class="form-actions"><button class="button" id="connect" type="submit">${t("Unganisha Telegram", "Connect Telegram")}</button><button class="button secondary" id="check-status" type="button">${t("Kagua hali", "Check status")}</button></div></form><p class="setup-feedback" id="feedback" role="status" aria-live="polite"></p><pre class="setup-result" id="setup-result" aria-label="${t("Hali ya bot", "Bot status")}" hidden></pre></section><section class="panel" aria-labelledby="owner-title"><h2 id="owner-title" style="margin-top:0">${t('Matangazo ya mmiliki', 'Owner announcements')}</h2><p class="field-note">${t('Unganisha akaunti ya @drcharlestz ili mmiliki aweze kuandaa na kuthibitisha taarifa za maboresho kwa groups zinazotumia Pilot. Uwezo huu ni wa mmiliki wa bot pekee.', 'Connect @drcharlestz so the bot owner can prepare and confirm product updates for groups using Pilot. This ability belongs only to the bot owner.')}</p><div class="form-actions"><button class="button secondary" id="owner-check" type="button">${t('Kagua mmiliki', 'Check owner')}</button><button class="button" id="owner-pair" type="button" hidden>${t('Tengeneza amri ya mara moja', 'Generate a one-time command')}</button></div><p class="setup-feedback" id="owner-feedback" role="status" aria-live="polite">${t('Tumia ufunguo ulioandika hapo juu kukagua akaunti ya mmiliki.', 'Use the key entered above to check the owner account.')}</p><p class="field-note" id="owner-bound" hidden></p><p class="field-note" id="owner-next" hidden></p><div id="owner-pairing" hidden><div class="form-field"><label for="owner-command">${t('Amri ya kutuma faraghani kwa bot', 'Command to send privately to the bot')}</label><input class="input" id="owner-command" type="text" readonly autocomplete="off" spellcheck="false" aria-describedby="owner-expiry"><span class="field-note" id="owner-expiry"></span></div><div class="form-actions"><button class="button secondary" id="owner-copy" type="button" disabled>${t('Nakili amri', 'Copy command')}</button><a class="button secondary" href="https://t.me/sautilinkpilotbot" target="_blank" rel="noopener noreferrer">${t('Fungua bot', 'Open bot')} ↗</a></div><p class="field-note" style="margin-top:16px">${t('Amri hii ni ya @drcharlestz pekee na inatumika mara moja. Haitahifadhiwa kwenye browser. Usiitumie kwenye group au kuisambaza.', 'This command is only for @drcharlestz and can be used once. It is not saved in the browser. Send it privately; do not share it in a group.')}</p></div></section><div class="warning"><p>${t("Baada ya kuunganisha, jaribu bot kwenye supergroup la majaribio. Ban halisi zinaweza kufuta pia ujumbe mwingine wa mtumiaji kwenye group.", "Once connected, try the bot in a test supergroup. Real bans may also delete the member’s other messages in the group.")}</p></div><p style="margin-top:28px"><a class="inline-link" href="${localeHref('/', lang)}">${t("Rudi kwenye ukurasa wa Pilot →", "Back to the Pilot homepage →")}</a></p></main>`, { script: setupScript(lang), robots: 'noindex,nofollow', lang, path: '/setup' });
}

export function renderPrivacy(lang = 'sw') {
  lang = normalizeLang(lang);
  const t = translator(lang);
  return layout(t('Faragha — SautiLink Pilot', 'Privacy — SautiLink Pilot'), t('Jinsi SautiLink Pilot inavyoshughulikia taarifa za moderation kwenye Telegram.', 'How SautiLink Pilot handles moderation information on Telegram.'), `<main id="main" class="document"><div class="eyebrow">${t("Faragha", "Privacy")}</div><h1>${t("Taarifa zinazosaidia<br>kusimamia group.", "Information that helps<br>moderate your group.")}</h1><p class="lead">${t("SautiLink Pilot huchakata ujumbe ambao Telegram inaiwasilisha ili kutambua links zisizoruhusiwa na forwarded messages, kisha kutekeleza sheria za group.", "SautiLink Pilot processes messages delivered by Telegram to identify unapproved links and forwarded messages, then apply the group’s rules.")}</p><h2>${t("Tunachohifadhi", "What we store")}</h2><p>${t("Bot huhifadhi taarifa zinazohitajika kwa moderation: utambulisho wa group na mtumiaji kwenye Telegram, idadi ya makosa, sababu ya hatua, utambulisho wa tukio na hali ya adhabu. Historia hii hutenganishwa kwa kila group.", "The bot stores the information needed for moderation: Telegram group and user identifiers, strike counts, the reason for an action, incident identifiers, and penalty status. This history is separate for each group.")}</p><p>${t("Maandishi ya ujumbe yanachunguzwa wakati wa kupokea tukio. Database ya moderation haihifadhi nakala kamili za mazungumzo. Jina la mtumiaji linaweza kuonekana kwenye tangazo la adhabu linalotumwa kwenye group.", "Message text is examined when an event arrives. The moderation database does not store full copies of conversations. A member’s name may appear in the penalty announcement sent to the group.")}</p><h2>${t("Rufaa na zana za group", "Appeals and group tools")}</h2><p>${t("Ukichagua kutuma rufaa, tunahifadhi maelezo unayoandika na uamuzi wa admin ili kuipitia. Maelezo haya yanaonekana kwako, kwa admins wa group husika na kwa waendeshaji wa huduma. Usitumie rufaa kutuma taarifa za siri zisizohitajika kwa ukaguzi.", "If you submit an appeal, we store your explanation and the admin’s decision for the review. These details are visible to you, the relevant group’s admins, and the service operators. Include only information needed for the review.")}</p><p>${t("Mipangilio ya group huhifadhi links au domains ambazo admin ameongeza kwenye whitelist, maandishi ya kukaribisha, maelezo ya sheria, maandishi ya ziada ya matangazo na chaguo la zana. Kikagua link huchakata anwani unayotuma bila kutembelea tovuti au kuhifadhi maandishi ya ukaguzi.", "Group settings store URLs or domains an admin adds to the allowlist, welcome text, rule notes, additional announcement text, and tool choices. The link checker processes the address you provide without visiting the website or saving the submitted check text.")}</p><p>${t("Anti-flood huhifadhi vitambulisho na muda wa ujumbe kwa kuhesabu kasi, bila maandishi yake. Kwa join requests tunahifadhi vitambulisho vya group na mwombaji, muda, hali ya ukaguzi na jibu la hatua fupi ya uthibitisho ikiwa imewashwa. Hatuhifadhi bio ya mwombaji au invite link.", "Flood control stores message identifiers and timestamps for counting, without their text. For join requests, we store group and applicant identifiers, timing, review status and the short challenge answer when enabled. We do not store the applicant’s bio or invite link.")}</p><p>${t("Ripoti na taarifa za matatizo hutumwa kwa admin aliyechagua kuzipokea, baada ya kukagua ruhusa yake tena. Chaguo la kupokea, rekodi ya kutumwa na historia ya mabadiliko ya admin huhifadhiwa ili kuonyesha uamuzi na kuzuia marudio.", "Reports and problem alerts go only to an admin who opted in, after checking their role again. Subscription choices, delivery records and a log of admin changes are stored to explain decisions and prevent repeats.")}</p><h2>${t('Matangazo ya huduma', 'Service announcements')}</h2><p>${t('Groups zinazotumia Pilot hupokea taarifa za bidhaa na maboresho zinazotumwa na mmiliki wa bot. Tunahifadhi orodha ya groups zinazotumia bot na hali ya muunganisho ili kupeleka taarifa hizi kwenye groups zinazostahili kuzipokea.', 'Groups using Pilot receive product updates and service announcements sent by the bot owner. We keep a registry of groups using the bot and their connection status to deliver these announcements to eligible groups.')}</p><p>${t('Mmiliki anaweza kuona historia ya matangazo ya siku 30 zilizopita. Maudhui ya rasimu na rekodi za kutuma za zamani huondolewa kwa awamu kwenye usafishaji uliopangwa; rekodi zikiwa nyingi, kuondoa zote kunaweza kuchukua muda zaidi. Orodha ya groups na hali zake huhifadhiwa kwa muda ambao group limeunganishwa au hali yake inahitajika kuendesha huduma. Hii haihifadhi nakala kamili za mazungumzo ya group.', 'The owner can view announcement history for the past 30 days. Older draft content and delivery records are removed in scheduled batches; clearing a large backlog may take longer. The group registry and connection state remain while a group is connected or its state is needed to operate the service. This does not store full copies of group conversations.')}</p><h2>${t("Lugha na paneli ya admin", "Language and the admin panel")}</h2><p>${t("Tunahifadhi chaguo la lugha ya mazungumzo yako ya faragha na chaguo la kila group. Kwa admin, tunakumbuka group alilochagua mwisho kwenye paneli ya faragha; rekodi hii yenyewe haitoi ruhusa za admin.", "We store your private-chat language choice and each group’s language choice. For an admin, we remember the last group selected in the private panel; this record does not grant admin access.")}</p><p>${t("Kwa matangazo ya moderation, tunahifadhi hali ya kutumwa, idadi ya majaribio, muda wa kujaribu tena na aina ya hitilafu. Telegram ikithibitisha kutumwa, tunahifadhi pia ID ya ujumbe. Taarifa hizi husaidia kuonyesha hali na kuepuka matangazo yanayojirudia.", "For moderation announcements, we store delivery status, attempt count, retry time, and the error category. When Telegram confirms delivery, we also store the message ID. These records help report status and avoid duplicate announcements.")}</p><h2>${t("Nani anaweza kuona taarifa hizi?", "Who can see this information?")}</h2><p>${t("Wanachama wanaweza kuona matangazo ambayo bot inatuma kwenye group lao. Wasimamizi wa huduma wanaweza kufikia taarifa za moderation kwa ajili ya kuendesha na kurekebisha huduma. Group moja halipewi historia ya makosa ya group jingine.", "Members can see the announcements the bot sends to their group. Service operators can access moderation records to run and troubleshoot the service. One group is not given another group’s strike history.")}</p><p>${t("Kabla ya kuonyesha taarifa za group faraghani, bot hukagua upya kuwa anayeomba bado ni owner au admin wa group hilo.", "Before showing group details privately, the bot checks again that the person requesting them is still that group’s owner or an admin.")}</p><h2>${t("Muda wa kuhifadhi", "How long records are kept")}</h2><p>${t("Usafishaji wa kila siku huondoa rekodi za updates zilizochakatwa zikiwa zaidi ya siku 7. Taarifa za tukio na matangazo yake huondolewa tukio likiwa zaidi ya siku 30. Group lililochaguliwa kwenye paneli ya admin huondolewa ikiwa rekodi yake haijasasishwa kwa zaidi ya siku 30.", "The daily cleanup removes processed update records older than 7 days. Incident records and their delivery details are removed once the incident is older than 30 days. A saved admin group selection is removed after more than 30 days without an update.")}</p><p>${t("Idadi ya makosa hubaki mpaka admin aisafishe. Chaguo la lugha na mipangilio ya group huhifadhiwa ili huduma iendelee kufanya kazi. Usafishaji huu haufuti matangazo yaliyotumwa Telegram.", "Strike counts remain until an admin resets them. Language choices and group settings are kept so the service can continue operating. This cleanup does not delete announcements already sent to Telegram.")}</p><p>${t("Rufaa huondolewa baada ya siku 30 tangu kusasishwa mwisho. Historia ya mabadiliko na rekodi za hatua au taarifa za admin huondolewa baada ya siku 30; alama ya kosa lililorekebishwa hubaki mpaka tukio lake limeondolewa. Maombi ya kujiunga huondolewa baada ya siku 7. Hesabu za anti-flood hutumia dirisha fupi la sekunde na rekodi za zamani huondolewa ujumbe mpya unapofika au kwenye usafishaji wa kila siku.", "Appeals are removed 30 days after their last update. Admin change logs and action or delivery records are removed after 30 days; a corrected-strike marker remains until its incident is removed. Join requests are removed after 7 days. Flood counters use a short window of seconds, with old records removed as new messages arrive or during daily cleanup.")}</p><p>${t("Orodha ya groups ambayo admin aliwahi kuthibitishwa kuyasimamia husafishwa baada ya siku 180 bila uthibitisho mpya. Kila matumizi bado hukagua uadmin upya. Mipangilio, whitelist, chaguo la kupokea ripoti na lugha hubaki mpaka zibadilishwe kwa huduma iendelee kufanya kazi.", "Known admin/group associations are cleaned up after 180 days without a new verification. Every use still checks current admin access. Settings, allowlist entries, report subscriptions and languages remain until changed so the service can continue operating.")}</p><h2>${t("Telegram na Cloudflare", "Telegram and Cloudflare")}</h2><p>${t("Telegram husafirisha taarifa za bot na kutekeleza kufuta ujumbe au kufungia mtumiaji. Worker na database ya huduma huendeshwa kwenye Cloudflare. Huduma hizo pia zina sera zao za kushughulikia taarifa.", "Telegram delivers bot events and carries out message deletion and member bans. The service’s Worker and database run on Cloudflare. Those services also have their own policies for handling information.")}</p><h2>${t("Maamuzi ya admins", "Admin decisions")}</h2><p>${t("Owner na admins wa group, anonymous admins, pamoja na posts zinazoingia automatically kutoka linked channel wanapewa msamaha wa sheria za moderation. Admin anaweza kubadilisha adhabu na kutumia amri ya kusafisha historia ya makosa ya mtumiaji ndani ya group husika.", "The group owner and admins, anonymous admins, and automatic posts from the linked channel are exempt from the moderation rules. An admin can change a penalty and use the command that resets a member’s strike history in that group.")}</p><h2>${t("Maswali au maombi", "Questions or requests")}</h2><p>${t("Kwa adhabu ndani ya group, fungua bot faraghani uone matukio yako na utume rufaa, au wasiliana na admin wa group hilo. Kwa maswali kuhusu huduma au taarifa zinazohifadhiwa, wasiliana na SautiLink kupitia", "For a group penalty, open the bot privately to view your cases and submit an appeal, or contact that group’s admin. For questions about the service or the information it stores, contact SautiLink through the")} <a class="inline-link" href="https://sautilink.com" target="_blank" rel="noopener noreferrer">${t("tovuti rasmi", "official website")}</a>.</p><p style="margin-top:32px"><a class="inline-link" href="${localeHref('/', lang)}">${t("Rudi kwenye SautiLink Pilot →", "Back to SautiLink Pilot →")}</a></p></main>`, { lang, path: '/privacy' });
}
